{
  "name": "oc-keep-going",
  "version": "0.0.0",
  "description": "Continue OpenCode sessions on an empty Enter using the selected model",
  "type": "module",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Sn0wo2/oc-keep-going.git"
  },
  "author": "Me0wo",
  "contributors": [
    "vimtor"
  ],
  "keywords": [
    "opencode",
    "opencode2",
    "opencode-plugin",
    "opencode2-plugin"
  ],
  "packageManager": "bun@1.4.4",
  "engines": {
    "node": ">=24"
  },
  "files": [
    "src",
    "dist",
    "LICENSE",
    "LICENSE-Original-MIT"
  ],
  "exports": {
    "./tui": "./src/tui.ts",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "scripts": {
    "build": "vite build",
    "check": "tsc --noEmit",
    "lint": "biome check --error-on-warnings .",
    "lint:fix": "biome check --write --error-on-warnings .",
    "security": "bun audit --registry=https://registry.npmjs.org",
    "ci": "bun run lint && bun run check && bun run build && bun run security",
    "prepack": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.7",
    "solid-js": "1.9.19"
  },
  "overrides": {
    "glob": "14.0.6",
    "minimatch": "11.0.8"
  },
  "devDependencies": {
    "@biomejs/biome": "2.6.7",
    "@types/bun": "1.4.4",
    "typescript": "7.0.2",
    "vite": "8.3.8",
    "vite-plugin-solid": "2.11.16"
  }
}
